package ama.localdev;
import ama.worker.*;import ama.transcript.*;import ama.storage.*;import ama.minutes.ControlledMinutesDataSource;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import java.lang.reflect.*;import java.sql.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.AbstractDataSource;import org.springframework.core.env.*;import com.fasterxml.jackson.databind.ObjectMapper;
/** Native precommit death of a fresh genuine Worker runtime. No SQL business fixtures or fake success. */
public final class LocalNativeWorkerCrashCheck {
 static final ObjectMapper JSON=new ObjectMapper();static void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
 static final class Source extends AbstractDataSource {
  final DataSource delegate;final String mode,meeting,task;final Path output;volatile String input;volatile boolean armed;final AtomicBoolean cut=new AtomicBoolean();
  Source(DataSource delegate,String mode,String meeting,String task,Path output){this.delegate=delegate;this.mode=mode;this.meeting=meeting;this.task=task;this.output=output;}
  static Object invoke(Object o,Method m,Object[] a)throws Throwable{try{return m.invoke(o,a);}catch(InvocationTargetException e){throw e.getCause();}}
  Object proxy(Object o,Class<?> type,InvocationHandler h){return Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},h);}
  Connection wrap(Connection actual){return(Connection)proxy(actual,Connection.class,(p,m,a)->{if(m.getName().equals("equals"))return p==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(p);Object result=invoke(actual,m,a);if(m.getName().equals("prepareStatement")&&a[0] instanceof String sql&&result instanceof PreparedStatement statement){var parameters=new HashMap<Integer,Object>();return proxy(statement,PreparedStatement.class,(s,sm,sa)->{if(sm.getName().startsWith("set")&&sa!=null&&sa.length>=2&&sa[0] instanceof Integer index)parameters.put(index,sa[1]);Object value=invoke(statement,sm,sa);
    String table=mode.equals("RAW")?"transcript_revision":mode.equals("CANDIDATE")?"generation_candidate":"external_document_mapping";boolean target=sql.startsWith("INSERT INTO "+table+"(")||sql.startsWith("INSERT INTO "+table+" (");
    if(armed&&target&&sm.getName().equals("executeUpdate")&&cut.compareAndSet(false,true)){
     check(value instanceof Number n&&n.intValue()==1,"Actual insert must return one row");check(!actual.getAutoCommit()&&org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive(),"Native cut must be inside actual uncommitted transaction");
     // The runtime is allowed to claim only this sole fresh task, so its production writer is bound to the fixture.
     if(mode.equals("RAW"))check(parameters.containsValue(meeting)&&(parameters.containsValue("RAW")||sql.contains("'RAW'")),"Exact actual RAW and meeting binding required");
     if(mode.equals("CANDIDATE"))check(parameters.containsValue(meeting)&&parameters.containsValue(task),"Exact actual candidate meeting and task binding required");
     if(mode.equals("MAPPING"))check(Objects.equals(parameters.get(1),input),"Exact accepted publication binding required");
     var report=new LinkedHashMap<String,Object>();report.put("phase","AFTER_REAL_INSERT_BEFORE_COMMIT");report.put("mode",mode);report.put("meetingId",meeting);report.put("taskId",task);report.put("table",table);report.put("actualInsertRows",1);report.put("actualTransactionActive",true);report.put("autoCommit",false);report.put("pid",ProcessHandle.current().pid());Files.writeString(output.resolve("cut.json"),JSON.writeValueAsString(report),StandardOpenOption.CREATE_NEW);System.out.flush();System.err.flush();Runtime.getRuntime().halt(86);
    }return value;});}return result;});}
  public Connection getConnection()throws SQLException{return wrap(delegate.getConnection());}public Connection getConnection(String u,String p)throws SQLException{return wrap(delegate.getConnection(u,p));}
 }
 static Map<String,Object> snapshot(JdbcTemplate j,String meeting,String task,String mode){var s=new LinkedHashMap<String,Object>();s.put("root",j.queryForMap("SELECT id,revision,cancel_epoch,stage,transcript_revision_id,transcript_confirmation_id,minutes_revision_id,element_set_id,final_confirmation_id,ever_published FROM meeting WHERE id=?",meeting));s.put("task",j.queryForMap("SELECT id,task_type,pool,state,attempt,lease_owner,input_kind,input_id,output_kind,output_id,last_error FROM durable_task WHERE id=? AND subject_kind='MEETING' AND subject_id=?",task,meeting));s.put("raw",j.queryForObject("SELECT COUNT(*) FROM transcript_revision WHERE meeting_id=? AND kind='RAW'",Long.class,meeting));s.put("orderedRawSegments",j.queryForList("SELECT s.body FROM transcript_segment s JOIN transcript_revision r ON r.id=s.revision_id WHERE r.meeting_id=? AND r.kind='RAW' ORDER BY r.id,s.ordinal",String.class,meeting));s.put("attempts",j.queryForList("SELECT attempt,outcome FROM task_attempt WHERE task_id=? ORDER BY attempt",task));s.put("segments",j.queryForObject("SELECT COUNT(*) FROM transcript_segment s JOIN transcript_revision r ON r.id=s.revision_id WHERE r.meeting_id=?",Long.class,meeting));s.put("files",j.queryForList("SELECT id,sha256,size_bytes,state FROM file_object WHERE meeting_id=? ORDER BY id",meeting));s.put("references",j.queryForObject("SELECT COUNT(*) FROM file_reference WHERE file_id IN (SELECT id FROM file_object WHERE meeting_id=?)",Long.class,meeting));s.put("batches",j.queryForObject("SELECT COUNT(*) FROM input_batch WHERE meeting_id=?",Long.class,meeting));s.put("inputs",j.queryForObject("SELECT COUNT(*) FROM transcription_input WHERE meeting_id=?",Long.class,meeting));s.put("completionEvents",j.queryForObject("SELECT COUNT(*) FROM task_outbox WHERE task_id=? AND event_type='TASK_SUCCEEDED'",Long.class,task));
  if(!mode.equals("RAW")){s.put("candidates",j.queryForObject("SELECT COUNT(*) FROM generation_candidate WHERE meeting_id=?",Long.class,meeting));s.put("bodies",j.queryForObject("SELECT COUNT(*) FROM minutes_revision WHERE meeting_id=?",Long.class,meeting));s.put("sets",j.queryForObject("SELECT COUNT(*) FROM element_set WHERE meeting_id=?",Long.class,meeting));s.put("executions",j.queryForList("SELECT id,task_attempt,state,execution_no,(marked_at IS NOT NULL) AS marked FROM external_execution WHERE task_id=? ORDER BY execution_no",task));}
  if(mode.equals("MAPPING")){s.put("mappings",j.queryForObject("SELECT COUNT(*) FROM external_document_mapping WHERE publication_id IN (SELECT id FROM publication WHERE meeting_id=?)",Long.class,meeting));s.put("publicationAttempts",j.queryForObject("SELECT COUNT(*) FROM publication_attempt p JOIN publication b ON b.id=p.publication_id WHERE b.meeting_id=?",Long.class,meeting));s.put("publication",j.queryForList("SELECT id,state,revision,confirmation_id FROM publication WHERE meeting_id=? ORDER BY id",meeting));}
  return s;
 }
 public static void main(String[] args)throws Exception{
  check("1".equals(System.getenv("AMA_LOCAL_DEV"))&&args.length==4,"Explicit daily native crash qualification required");Path file=Path.of(args[0]).toRealPath();check(file.getParent().endsWith(Path.of(".tools/local-app"))&&Files.size(file)<65536,"Daily local configuration required");String mode=args[2];boolean inspect=mode.startsWith("INSPECT_");if(inspect)mode=mode.substring(8);check(Set.of("RAW","CANDIDATE","MAPPING").contains(mode),"Known exact cut required");Path output=Path.of(args[3]).toRealPath();check(output.startsWith(file.getParent().resolve("native-crash")),"Fresh daily qualification directory required");var p=new Properties();try(var in=Files.newInputStream(file)){p.load(in);}String url=p.getProperty("database.url");check(url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"),"Dedicated owned local DB required");var fixture=JSON.readTree(Files.readString(Path.of(args[1])));String task=fixture.get("taskId").asText(),meeting=fixture.get("meetingId").asText();UUID.fromString(task);UUID.fromString(meeting);var source=new Source(ControlledMinutesDataSource.create(url,p.getProperty("database.user"),p.getProperty("database.password")),mode,meeting,task,output);var j=new JdbcTemplate(source);j.setQueryTimeout(5);
  if(inspect){var result=snapshot(j,meeting,task,mode);Files.writeString(output.resolve("inspection.json"),JSON.writeValueAsString(result));System.out.println(JSON.writeValueAsString(result));return;}
  check(!Files.exists(output.resolve("cut.json"))&&!Files.exists(output.resolve("before.json")),"New cut evidence required");var pending=j.queryForList("SELECT id FROM durable_task WHERE state IN ('READY','RUNNING','RECONCILING') ORDER BY id",String.class);check(pending.equals(List.of(task)),"Only this fresh task may be pending in the genuine runtime");var before=snapshot(j,meeting,task,mode);@SuppressWarnings("unchecked")var originalTask=(Map<String,Object>)before.get("task");check("READY".equals(originalTask.get("state"))&&((Number)originalTask.get("attempt")).longValue()==0,"Fresh unclaimed task required");check((mode.equals("RAW")?"TRANSCRIPT_IMPORT_V1":mode.equals("CANDIDATE")?"MINUTES_GENERATE_V1":"KNOWLEDGE_PUBLISH_V1").equals(originalTask.get("task_type")),"Exact task type and cut must match");source.input=(String)originalTask.get("input_id");Files.writeString(output.resolve("before.json"),JSON.writeValueAsString(before),StandardOpenOption.CREATE_NEW);
  var env=new StandardEnvironment();env.getPropertySources().addFirst(new PropertiesPropertySource("daily",p));var configured=ConfiguredProcessing.read(env);var definitions=ConfiguredBackends.read(env);var provider=new TranscriptWorkerRuntimeProvider(source,definitions,configured.read(),configured.canonical(),configured.preparation(),"LOCAL_NATIVE_"+mode+"_"+output.getFileName(),1,ConfiguredMinutes.read(env,configured.read(),configured.index()),ConfiguredPublication.read(env,configured.read(),configured.index()));
  try(var runtime=(TranscriptWorkerRuntimeProvider.Runtime)provider.create()){source.armed=true;runtime.start();long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(90);while(System.nanoTime()<deadline){Thread.sleep(100);String state=j.queryForObject("SELECT state FROM durable_task WHERE id=?",String.class,task);check(!Set.of("SUCCEEDED","FAILED","CANCELLED","STALE").contains(state),"Task ended without the intended native cut");}throw new IllegalStateException("Native cut not reached within bounded wait");}
 }
}
